def test_guess_pay_annualizes_hourly():
    assert _guess_pay("Contract", "$80/hr") == 160_000  # 80 * 40 * 50
    assert _guess_pay("Contract", "$80/hr", hours=20) == 80_000
    assert _guess_pay("", "$80 - $100 / Hour") == 200_000
    from src.engine import _parse_pay
    assert _parse_pay("$80 - $100 / Hour") == (160_000, 200_000)
    assert _parse_pay("$80–$100/hr") == (160_000, 200_000)
    assert _parse_pay("$80 an hour") == (None, 160_000)
    assert _parse_pay("$800 day") == (None, 200_000)
    assert _parse_pay("$800day") == (None, 200_000)
    assert _parse_pay("$3,000 week") == (None, 150_000)
    assert _parse_pay("$3000 week") == (None, 150_000)
    assert _parse_pay("$3 000 week") == (None, 150_000)
    assert _parse_pay("$15 000 month") == (None, 180_000)
    assert _parse_pay("$3 000 week travel") == (None, None)
    assert _parse_pay("$3000 / week") == (None, 150_000)
    assert _parse_pay("$3000 weekly") == (None, 150_000)
    assert _parse_pay("$2000-$3000 week") == (100_000, 150_000)
    assert _parse_pay("$15,000 month") == (None, 180_000)
    assert _parse_pay("$15000 month") == (None, 180_000)
    assert _parse_pay("$3000 biweekly") == (None, 75_000)
    assert _parse_pay("$3000 / biweekly") == (None, 75_000)
    assert _parse_pay("$3000/biweekly") == (None, 75_000)
    assert _parse_pay("$3000 / bi-weekly") == (None, 75_000)
    assert _parse_pay("$3000/fortnight") == (None, 75_000)
    assert _parse_pay("$3000 / fortnightly") == (None, 75_000)
    assert _parse_pay("$3000 / semi-monthly") == (None, 72_000)
    assert _parse_pay("$3000/semimonthly") == (None, 72_000)
