def test_guess_hours_from_text_not_job_type():
    assert _guess_hours("Engineer", "20 hrs/week") == 20
    assert _guess_hours("Engineer", "32 hours a week") == 32
    assert _guess_hours("Engineer", "eight hours a week") == 8
    assert _guess_hours("Engineer", "nine hours per week") == 9
    assert _guess_hours("Engineer", "ten hours a week") == 10
    assert _guess_hours("Engineer", "eleven hours a week") == 11
    assert _guess_hours("Engineer", "twelve hours weekly") == 12
    assert _guess_hours("Engineer", "thirteen hours a week") == 13
    assert _guess_hours("Engineer", "thirteen hours a fortnight") == 6
    assert _guess_hours("Engineer", "eight hours a fortnight") == 4
    assert _guess_hours("Engineer", "ten hours per fortnight") == 5
    assert _guess_hours("Engineer", "fourteen hours a fortnight") is None
    assert _guess_hours("Engineer", "fourteen hours a week") is None
    assert _guess_hours("Engineer", "32 hours a week. This is a full-time role.") == 32
    assert _guess_hours("Engineer", "32 hours each week") == 32
    assert _guess_hours("Engineer", "32 hrs each week") == 32
    assert _guess_hours("Engineer", "32 hours every week") == 32
    assert _guess_hours("Engineer", "32 hours wkly") == 32
    assert _guess_hours("Engineer", "hours each week: 32") == 32
    assert _guess_hours("Engineer", "hours every week: 32") == 32
    assert _guess_hours("Engineer", "hours wkly: 32") == 32
    assert _guess_hours("Engineer", "wkly hours: 32") == 32
    assert _guess_hours("Engineer", "32 wkly hours") == 32
    assert _guess_hours("Engineer", "hours of work each week: 32") == 32
    assert _guess_hours("Engineer", "hours of work every week: 32") == 32
    assert _guess_hours("Engineer", "hours of work for each week: 32") == 32
    assert _guess_hours("Engineer", "hours of work for every week: 32") == 32
    assert _guess_hours("Engineer", "hours of work for the week: 32") == 32
    assert _guess_hours("Engineer", "hours of work for week: 32") == 32
    assert _guess_hours("Engineer", "32 hours of work for each week") == 32
    assert _guess_hours("Engineer", "32 hours of work for every week") == 32
    assert _guess_hours("Engineer", "32 hours of work for the week") == 32
    assert _guess_hours("Engineer", "hours of working for each week: 32") == 32
    assert _guess_hours("Engineer", "hours of the work for each week: 32") == 32
    assert _guess_hours("Engineer", "32 hours of work for each week meeting") is None
    assert _guess_hours("Engineer", "hours of work per the week: 32") == 32
    assert _guess_hours("Engineer", "hours of work per each week: 32") == 32
    assert _guess_hours("Engineer", "hours of work per every week: 32") == 32
    assert _guess_hours("Engineer", "32 hours of work per the week") == 32
    assert _guess_hours("Engineer", "32 hours of work per each week") == 32
    assert _guess_hours("Engineer", "32 hours of work per every week") == 32
    assert _guess_hours("Engineer", "hours of working per the week: 32") == 32
    assert _guess_hours("Engineer", "hours of the work per each week: 32") == 32
    assert _guess_hours("Engineer", "32 hours of work per the week meeting") is None
    assert _guess_hours("Engineer", "hours of work per this week: 32") is None
    assert _guess_hours("Engineer", "hours work each week: 32") == 32
    assert _guess_hours("Engineer", "hours work every week: 32") == 32
    assert _guess_hours("Engineer", "hours work a week: 32") == 32
    assert _guess_hours("Engineer", "hours work wkly: 32") == 32
    assert _guess_hours("Engineer", "hrs work each week: 32") == 32
    assert _guess_hours("Engineer", "hours: 32 each week") == 32
    assert _guess_hours("Engineer", "hours: 32 every week") == 32
    assert _guess_hours("Engineer", "hours: 32 wkly") == 32
    assert _guess_hours("Engineer", "hours of work: 32 each week") == 32
    assert _guess_hours("Engineer", "hours of work: 32 every week") == 32
    assert _guess_hours("Engineer", "hours of work: 32 wkly") == 32
    assert _guess_hours("Engineer", "hours work: 32 each week") == 32
