def test_html_is_gone_removed_listing_banner():
    from src.engine import _html_is_gone, _html_is_index

    removed = (
        "<title>Machine learning Engineer - Agentic Retrieval - Zoom | Built In</title>"
        "<p>Sorry, this job was removed at 08:39 a.m. (UTC) on Friday, Aug 28, 2026</p>"
        "<p>Similar Jobs Square Account Executive $151,800 - $332,200</p>"
    )
    assert _html_is_gone(removed) is True
    assert _html_is_index(removed, "https://www.builtin.com/job/ml/10377512") is False
    assert (
        _html_is_gone(
            "<title>ML Engineer - Zoom | Built In</title>"
            "<p>Design hybrid retrieval systems. $180,000 - $220,000</p>"
        )
        is False
    )
    assert (
        _html_is_gone(
            "<title>Engineer</title>"
            "<p>Applications removed from consideration stay on file.</p>"
        )
        is False
    )
    filled = (
        "<title>Senior ML Engineer - Acme</title>"
        "<p>This position has been filled.</p>"
        "<p>$180,000 - $220,000 a year</p>"
    )
    assert _html_is_gone(filled) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>This role has already been filled.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>This position has already been filled.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>We've already filled this role.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>We already filled this search.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>We've already filled this meeting.</p><p>$180,000</p>"
    ) is False
    assert (
        _html_is_gone(
            "<title>Engineer</title>"
            "<p>Once this position has been filled, the team will grow.</p>"
            "<p>$180,000 a year</p>"
        )
        is False
    )
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>Once this position has already been filled, the team will grow.</p>"
        "<p>$180,000</p>"
    ) is False
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>This role was filled.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>This position was filled internally.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>This role was already filled.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>Role was filled.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>This role was closed.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>This meeting was filled.</p><p>$180,000</p>"
    ) is False
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>Once this role was filled, we grew.</p><p>$180,000</p>"
    ) is False
    assert _html_is_gone(
        "<title>Engineer</title><p>This job posting has expired.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title><p>This role has lapsed.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title><p>This posting has lapsed.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title><p>Listing has lapsed.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title><p>This meeting has lapsed.</p><p>$180,000</p>"
    ) is False
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>Once this role has lapsed, we archive.</p><p>$180,000</p>"
    ) is False
    assert _html_is_gone(
        "<title>Engineer</title><p>This posting is no longer active.</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title><p>This role is no longer vacant.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title><p>This position is no longer vacant.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title><p>Position is no longer vacant.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title><p>This meeting is no longer vacant.</p><p>$180,000</p>"
    ) is False
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>Once this role is no longer vacant, we grow.</p><p>$180,000</p>"
    ) is False
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>This role is no longer needed.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>This requisition is no longer needed.</p><p>$180,000</p>"
    ) is True
    assert _html_is_gone(
        "<title>Engineer</title>"
        "<p>Role is no longer needed.</p><p>$180,000</p>"
    ) is True
